import math

def is_perfect_cube(n):
    if n == 0:
        return True

    # Calculate the cubic root and round to the nearest integer
    # We use floating point math carefully, rounding to the nearest integer
    # and then checking if cubing it returns the original number.
    try:
        root = round(abs(n)**(1/3))
        if root**3 == abs(n):
            # If the cube root matches the absolute value, it's a perfect cube.
            # We adjust the sign.
            if n < 0:
                return (-root)**3 == n
            else:
                return root**3 == n
    except OverflowError:
        # Should not happen for typical integers in this range
        return False
    return False

def check_equation(x):
    A = 8 * x - 41
    C_sq = (x + 3)**2
    E_x = A * C_sq

    is_cube = is_perfect_cube(E_x)

    print(f"x = {x}: E(x) = {E_x}. Is perfect cube? {is_cube}")
    return is_cube

